import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import solc from 'solc'

const root = process.cwd()
const contractsDirectory = path.join(root, 'contracts')
const artifactsDirectory = path.join(root, 'artifacts', 'contracts')
const generatedDirectory = path.join(root, 'src', 'generated')
const publicDirectory = path.join(root, 'public', 'contracts')

async function writeIfChanged(file, content) {
  try {
    if (await readFile(file, 'utf8') === content) return
  } catch {
    // The generated file does not exist yet.
  }
  await writeFile(file, content)
}

async function walk(directory) {
  const entries = await readdir(directory, { withFileTypes: true })
  const files = await Promise.all(entries.map(async (entry) => {
    const fullPath = path.join(directory, entry.name)
    if (entry.isDirectory()) return walk(fullPath)
    return entry.name.endsWith('.sol') ? [fullPath] : []
  }))
  return files.flat()
}

const sourceFiles = await walk(contractsDirectory)
const sources = Object.fromEntries(await Promise.all(sourceFiles.map(async (file) => [
  path.relative(root, file).replaceAll('\\', '/'),
  { content: await readFile(file, 'utf8') },
])))
const catalog = JSON.parse(await readFile(path.join(contractsDirectory, 'catalog.json'), 'utf8'))

const input = {
  language: 'Solidity',
  sources,
  settings: {
    optimizer: { enabled: true, runs: 300 },
    evmVersion: 'cancun',
    outputSelection: {
      '*': { '*': ['abi', 'evm.bytecode.object', 'evm.deployedBytecode.object'] },
    },
  },
}

const output = JSON.parse(solc.compile(JSON.stringify(input)))
const messages = output.errors ?? []
for (const message of messages) {
  const line = `${message.severity}: ${message.formattedMessage}`
  if (message.severity === 'error') console.error(line)
  else console.warn(line)
}
if (messages.some((message) => message.severity === 'error')) process.exit(1)

const byName = new Map()
for (const [sourceName, contracts] of Object.entries(output.contracts ?? {})) {
  for (const [contractName, artifact] of Object.entries(contracts)) {
    byName.set(contractName, { sourceName, contractName, ...artifact })
  }
}

await rm(artifactsDirectory, { recursive: true, force: true })
await mkdir(artifactsDirectory, { recursive: true })
await mkdir(generatedDirectory, { recursive: true })
await mkdir(publicDirectory, { recursive: true })

const webAbis = {}
const manifestContracts = {}
for (const definition of catalog) {
  const compiled = byName.get(definition.contractName)
  if (!compiled) throw new Error(`Missing compiled contract ${definition.contractName}`)
  const artifact = {
    key: definition.key,
    title: definition.title,
    category: definition.category,
    contractName: definition.contractName,
    sourceName: compiled.sourceName,
    abi: compiled.abi,
    bytecode: `0x${compiled.evm.bytecode.object}`,
    deployedBytecode: `0x${compiled.evm.deployedBytecode.object}`,
    constructor: definition.constructor,
    compiler: solc.version(),
  }
  await writeFile(
    path.join(artifactsDirectory, `${definition.key}.json`),
    `${JSON.stringify(artifact, null, 2)}\n`,
  )
  webAbis[definition.key] = compiled.abi
  manifestContracts[definition.key] = {
    title: definition.title,
    contractName: definition.contractName,
    category: definition.category,
  }
}

const generated = `// Generated by scripts/compile-contracts.mjs. Do not edit.\n` +
  `export const CONTRACT_ABIS = ${JSON.stringify(webAbis, null, 2)} as const\n\n` +
  `export type ContractKey = keyof typeof CONTRACT_ABIS\n`
await writeIfChanged(path.join(generatedDirectory, 'contracts.ts'), generated)
await writeFile(path.join(publicDirectory, 'manifest.json'), `${JSON.stringify({
  compiler: solc.version(),
  generatedAt: new Date().toISOString(),
  contracts: manifestContracts,
}, null, 2)}\n`)

console.log(`Compiled ${catalog.length} Zenith suite contracts with ${solc.version()}.`)
